import{_ as a,H as e,f as t,i as r}from"./chunks/framework.Cvt1eIE0.js";const _=JSON.parse('{"title":"PIGLIN KING 第一巻 黄金王の誕生","description":"","frontmatter":{"title":"PIGLIN KING 第一巻 黄金王の誕生","outline":"deep"},"headers":[],"relativePath":"story/1-1.md","filePath":"story/1-1.md"}'),o={name:"story/1-1.md"};function i(n,p,l,s,h,d){return e(),t("div",null,[...p[0]||(p[0]=[r('<h1 id="piglin-king" tabindex="-1">PIGLIN KING <a class="header-anchor" href="#piglin-king" aria-label="Permalink to &quot;PIGLIN KING&quot;">​</a></h1><h2 id="第一巻-黄金王の誕生" tabindex="-1">第一巻 黄金王の誕生 <a class="header-anchor" href="#第一巻-黄金王の誕生" aria-label="Permalink to &quot;第一巻 黄金王の誕生&quot;">​</a></h2><hr><h1 id="第一章-真紅の森の少年" tabindex="-1">第一章 真紅の森の少年 <a class="header-anchor" href="#第一章-真紅の森の少年" aria-label="Permalink to &quot;第一章 真紅の森の少年&quot;">​</a></h1><p>まだ誰も彼を「黄金王」と呼んでいなかった頃の話だ。</p><p>真紅の森は、いつも燃えていた。</p><p>燃えているわけではない。</p><p>ただ、そう見える。</p><p>天井を覆う巨大なキノコたちが、暗いネザーの空に赤と橙の光を散らして、まるで世界そのものが夕焼けに溶け込んでいるかのように輝いていた。奇妙なほど美しく、しかし奇妙なほど不安定な、そんな森だった。</p><p>その深紅の光の中に、一匹の少年がいた。</p><p>仰向けに寝転んで。</p><p>溶岩の光に照らされた「空」を。</p><p>ただじっと、見上げていた。</p><p>「いつか、ネザー中を旅してみたいな。」</p><p>誰に言うともなく呟く。</p><p>その言葉は真紅の空へ消えていった。</p><p>まるで煙のように。</p><p>少年の名は、</p><p>Aurex Goldtusk。</p><p>黄金色の牙を持つ、若きピグリン。</p><p>鍛冶職人の父と、交易商人の母のもとで育った。どこにでもいる、ごく普通の少年だった。</p><p>少なくとも、そう見えた。</p><p>剣の腕は、同い年の中では抜きん出ていた。父から叩き込まれた剣術は、骨の髄まで染み込んでいた。</p><p>しかし彼が本当に好きだったのは、剣ではなかった。</p><p>古びた本を読むこと。</p><p>誰も知らない遺跡を探検すること。</p><p>そして、溶岩の流れる音を聞きながら、何もせずにいること。</p><p>争いが、嫌いだった。</p><p>「どうしてみんな戦うんだろう……。」</p><p>市場で喧嘩が起きるたびに、戦争の噂が流れるたびに、オーレックスはそう呟いた。</p><p>その声には怒りではなく、純粋な疑問があった。</p><p>「なぜ空は暗いのか」と聞く子供のような、素朴で、しかし誰も答えられない問いだった。</p><p>そのたびに、父は苦笑して言った。</p><p>「いつか、お前にも分かるさ。」</p><p>父の手は大きかった。</p><p>剣を鍛え続けた、鉄のような手。</p><p>しかし、息子の頭を撫でる時だけは、驚くほど優しかった。</p><p>「分かりたくないけど。」</p><p>オーレックスはいつも、そう心の中で返した。</p><p>分かってしまう日が来ることを、どこかで恐れていたから。</p><hr><h1 id="第二章-出会い" tabindex="-1">第二章 出会い <a class="header-anchor" href="#第二章-出会い" aria-label="Permalink to &quot;第二章 出会い&quot;">​</a></h1><p>十五歳の、ある日のことだった。</p><p>「夏」といっても、ネザーに季節はない。ただ、あの日の溶岩は、いつもより明るく輝いていた気がする。</p><p>市場へ向かう道の途中。</p><p>路地の奥から、荒々しい声が聞こえた。</p><p>「金を置いていけ！！」</p><p>オーレックスは立ち止まった。</p><p>路地を覗く。</p><p>三人の盗賊が、大柄なピグリンを取り囲んでいた。体格だけ見れば、大柄な方がずっと強そうだった。しかし、数が悪い。</p><p>「嫌だ！」</p><p>大柄なピグリンが叫んだ。</p><p>盗賊の一人が剣を抜く。</p><p>「あ。」</p><p>オーレックスが動いていたのは、考えるより先だった。</p><p>「待て！！」</p><p>路地に飛び込む。</p><p>三対一が、三対二になった。</p><p>そして。</p><p>数分後。</p><p>路地には、盗賊たちの背中しか残っていなかった。逃げていった。全速力で。</p><p>「あー笑える！！」</p><p>大柄なピグリンが笑い声を上げた。腹を抱えて。天井を仰ぎながら。</p><p>「助かったぜ！！ありがとな！！」</p><p>豪快な笑い声だった。</p><p>まるで雷が転がるような声だった。</p><p>「俺はスターリン！斧なら誰にも負けねえ！」</p><p>自慢するように大斧を肩に担いだ。刃は欠けていた。今日だけで相当使ったのだと分かった。</p><p>「俺はオーレックス。Aurex Goldtusk。」</p><p>「いい名前じゃねえか！黄金の牙か！なんか強そうだな！」</p><p>「……別に強くないけど。」</p><p>「十分強えよ！さっき見てたぞ！剣、速えな！」</p><p>そう言って、スターリンは大きな手を差し出した。</p><p>オーレックスは少しためらってから、その手を握った。</p><p>スターリンの手はごつごつしていた。傷だらけで、節くれ立っていて、でも温かかった。</p><p>二人はそうして友人になった。あの路地の、薄暗い石灰岩の壁の前で。</p><hr><p>数日後。</p><p>二人は古代の砦跡を探索していた。</p><p>オーレックスは遺跡が好きで、スターリンは「面白そう」という理由だけでついてきた。</p><p>「ここ、誰も来ないんだな。」</p><p>「だから面白いんだ。」</p><p>「宝でも眠ってんじゃねえか？」</p><p>「そういう話じゃ――」</p><p>突然。</p><p>後ろから声がした。</p><p>「そこ、踏まない方がいい。」</p><p>二人は振り返った。</p><p>いつからいたのか、小柄なピグリンが壁に寄りかかっていた。眼鏡の奥の目が、静かにこちらを見ている。</p><p>「その石、感圧板。踏んだら天井から矢が飛ぶ構造になってる。設計は古代ヴォールト文明のもので、精度はかなり高い。当たれば即死かな。」</p><p>淡々とした口調だった。まるで天気の話をするように。</p><p>「……なんで教えてくれるんだ？」</p><p>「君たちが死んだら、後で調査しにくくなるから。」</p><p>「俺たちの心配じゃなくて自分のためか。」</p><p>「両方かな。」</p><p>その瞬間。</p><p>カチッ。</p><p>という音がした。</p><p>「え？」</p><p>スターリンの足元。</p><p>「お前！！今踏んだだろ！！」</p><p>バシュッ！！</p><p>「ぎゃああああああ！！」</p><p>三本の矢が石壁に刺さった。スターリンは奇跡的に無傷で、壁に張り付いていた。</p><p>ゆっくりと振り返る。</p><p>「……助かった。」</p><p>「幸運だね。」</p><p>小柄なピグリンは静かに言った。</p><p>「ちょっと待って、今踏んだよね？なんで僕が言った直後に踏むの？」</p><p>「反射的に……。」</p><p>「反射で感圧板を踏む奴を初めて見た。」</p><p>オーレックスは笑いをこらえるのに必死だった。</p><p>「僕はピックバーグ。」</p><p>小柄なピグリンは言った。</p><p>「遺跡研究家。古代文明、機械仕掛け、罠の設計、全部専門。」</p><p>「俺はスターリン。斧使い。」</p><p>「で、こちらが――」</p><p>「オーレックス。」</p><p>ピックバーグはオーレックスをじっと見た。遺跡の壁画でも眺めるような目で。</p><p>「黄金の牙……珍しい色だ。」</p><p>「……よく言われる。」</p><p>「いい意味で言ったんだけど。」</p><p>「分かってる。」</p><p>三匹は少しの間、砦の入口に立ち尽くしていた。誰も何も言わなかった。</p><p>しかし。</p><p>気が付けば、三匹は並んで砦の奥へ歩いていた。</p><p>なぜかは、誰も言えなかった。ただ、そうなっていた。</p><p>こうして三匹の友情が、古い石と罠と笑い声の中で、始まった。</p><hr><h1 id="第三章-炎の夜" tabindex="-1">第三章 炎の夜 <a class="header-anchor" href="#第三章-炎の夜" aria-label="Permalink to &quot;第三章 炎の夜&quot;">​</a></h1><p>平和は、前触れなく壊れる。</p><p>後から思えば、あの夜の前にも予兆はあった。</p><p>旅商人が減った。</p><p>隣国から難民が来るようになった。</p><p>父の表情が、日に日に硬くなっていった。</p><p>しかし少年は、気づけなかった。</p><p>気づきたくなかったのかもしれない。</p><p>そして夜が来た。</p><p>光だった。</p><p>最初は、綺麗だと思った。空が赤く輝いていたから。</p><p>しかし。</p><p>それは夕焼けではなかった。</p><p>火だった。</p><p>「逃げろ！！」</p><p>誰かの声が、夜を切り裂いた。</p><p>「戦争だ！！隣国の軍が来た！！」</p><p>真紅の森が、本当に燃え始めた。</p><p>悲鳴。</p><p>足音。</p><p>崩れ落ちる家。</p><p>「オーレックス！！」</p><p>父の声。</p><p>「逃げろ！村の人たちを連れて、西へ！！」</p><p>「父さんは！？」</p><p>「いいから行け！！」</p><p>父の大きな手が、オーレックスの背を押した。</p><p>あの、鉄のように硬くて、しかし優しい手が。最後に、押した。</p><p>だから。</p><p>オーレックスは走った。走りながら何度も振り返った。父の背中が炎の中に小さくなっていくのを見た。見えなくなった。煙の中に。</p><p>母も、最後まで逃げなかった。</p><p>避難する人々の群れに混ざって、「こっちよ！急いで！足が痛い人は！」と誰かの手を引いて、誰かを助けて、助け続けて、気が付けばいなかった。</p><p>母の笑顔を最後に見たのは、いつだったか。</p><p>後悔するより先に、全てが終わっていた。</p><p>全てを失った。</p><p>煙の中で、炎の残骸の中で、オーレックスは膝をついた。</p><p>体が震えていた。泣こうとした。しかし涙は出なかった。出方を忘れたかのように、目の奥で止まっていた。</p><p>「なんで……。」</p><p>「なんでなんだよ……。」</p><p>声が掠れた。</p><p>暗闇の中に、一人だった。</p><p>その肩に、重い手が置かれた。</p><p>スターリンの手だった。あの日、路地で握った、傷だらけの大きな手。</p><p>「お前は一人じゃねえ。」</p><p>声が、いつもの豪快さを失っていた。珍しく、静かで、低い声で。</p><p>ピックバーグも傍らに座った。</p><p>「僕たちがいる。」</p><p>眼鏡の奥の目が、真っ直ぐにオーレックスを見ていた。いつもの分析する目ではなく、ただ一緒にいると言っている目で。</p><p>その言葉だけが、唯一の光だった。</p><p>暗い夜に。</p><p>煙の匂いの中に。</p><p>たった一つの、灯りだった。</p><p>長い沈黙の後。</p><p>オーレックスは顔を上げた。</p><p>「行こう。」</p><p>「え？」</p><p>「旅に出よう。」</p><p>「旅って……どこへ？」</p><p>「分からない。」</p><p>「でも。」</p><p>「こんな悲劇が、また起きてほしくない。」</p><p>「だから、動いていたい。」</p><p>スターリンは一瞬だけ目を細め、それからいつもの顔に戻った。</p><p>「待ってました！」</p><p>ピックバーグは小さく頷いた。</p><p>「行くしかないね。」</p><p>真紅の森の残骸の中で。</p><p>三匹は立ち上がった。</p><p>これが、始まりだった。</p><p>まだ誰も、そうとは知らない。始まりだった。</p>',199)])])}const u=a(o,[["render",i]]);export{_ as __pageData,u as default};
